import { CustomTextStyling, PNull, Pos, RecursiveReadonly, TranslatedText } from "@bloxd"
import { MaybeRecursiveReadonly } from "./types"

export function style(msg: string | TranslatedText, colour: string): CustomTextStyling {
	return [{ str: msg, style: { colour: colour } }]
}

export function roundOutwardsToChunkBoundary(rect: RecursiveReadonly<[Pos, Pos]>): [Pos, Pos] {
	const { low, high } = getLowHigh(rect)
	return [
		[Math.floor(low[0] / 32) * 32, Math.floor(low[1] / 32) * 32, Math.floor(low[2] / 32) * 32],
		[Math.ceil(high[0] / 32) * 32, Math.ceil(high[1] / 32) * 32, Math.ceil(high[2] / 32) * 32],
	]
}

export function getDimensions(rect: MaybeRecursiveReadonly<[Pos, Pos]>): { l: number; w: number; h: number } {
	const [pos1, pos2] = rect
	return {
		l: Math.abs(pos1[0] - pos2[0]),
		w: Math.abs(pos1[1] - pos2[1]),
		h: Math.abs(pos1[2] - pos2[2]),
	}
}

export function getLowHigh(rect: RecursiveReadonly<[Pos, Pos]>): { low: Pos; high: Pos } {
	const [pos1, pos2] = rect
	return {
		low: [Math.min(pos1[0], pos2[0]), Math.min(pos1[1], pos2[1]), Math.min(pos1[2], pos2[2])],
		high: [Math.max(pos1[0], pos2[0]), Math.max(pos1[1], pos2[1]), Math.max(pos1[2], pos2[2])],
	}
}

export function preloadRect(rect: MaybeRecursiveReadonly<[Pos, Pos]>) {
	// Preloads the chunks in the rectangle to ensure they're loaded when the game starts
	const { low: mapLow, high: mapHigh } = getLowHigh(rect)
	for (let x = mapLow[0]; x < mapHigh[0]; x += 32) {
		for (let y = mapLow[1]; y < mapHigh[1]; y += 32) {
			for (let z = mapLow[2]; z < mapHigh[2]; z += 32) {
				api.getBlock(x, y, z)
			}
		}
	}
}

function numToTwoDigStr(n: number) {
	return (n < 10 ? "0" : "") + n
}

/**
 * Display ms in format mm:ss, or hh:mm:ss if hours > 0
 * ss is rounded up (i.e. if ms > 0 then ss always 01 or more)
 */
export function displayMs(ms: number): string {
	const totalS = Math.ceil(ms / 1000) // Round up to nearest second
	const hours = Math.floor(totalS / 3600)
	const min = Math.floor((totalS % 3600) / 60)
	const sec = Math.floor(totalS % 60)
	if (hours > 0) {
		return `${hours}:${numToTwoDigStr(min)}:${numToTwoDigStr(sec)}`
	}
	return `${min}:${numToTwoDigStr(sec)}`
}
